head.script:
scwin.screenId = "jldinf00006";

///////// 1. 변수 및 선언 영역 /////////

scwin.chrg_tel_no = undefined;

scwin.encryp_cellphone_no = undefined;

scwin.chrg_fax_no = undefined;

scwin.encryp_chrg_email = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_IsurMessage", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("message")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getComponent('dma_searchMemberReq').get('IsurNewYn') === "Y") {
            ($c.util.getComponent("txt_joinMember") && $c.util.getComponent("txt_joinMember").show ? $c.util.getComponent("txt_joinMember").show() : console.warn('[sdd] show 대상 미해결: ' + "txt_joinMember"));
            ($c.util.getComponent("joinMember1") && $c.util.getComponent("joinMember1").show ? $c.util.getComponent("joinMember1").show() : console.warn('[sdd] show 대상 미해결: ' + "joinMember1"));
            ($c.util.getComponent("joinMember2") && $c.util.getComponent("joinMember2").show ? $c.util.getComponent("joinMember2").show() : console.warn('[sdd] show 대상 미해결: ' + "joinMember2"));
            ($c.util.getComponent("joinMember3") && $c.util.getComponent("joinMember3").show ? $c.util.getComponent("joinMember3").show() : console.warn('[sdd] show 대상 미해결: ' + "joinMember3"));
        } else {
            ($c.util.getComponent("txt_joinMember") && $c.util.getComponent("txt_joinMember").hide ? $c.util.getComponent("txt_joinMember").hide() : console.warn('[sdd] hide 대상 미해결: ' + "txt_joinMember"));
            ($c.util.getComponent("joinMember1") && $c.util.getComponent("joinMember1").hide ? $c.util.getComponent("joinMember1").hide() : console.warn('[sdd] hide 대상 미해결: ' + "joinMember1"));
            ($c.util.getComponent("joinMember2") && $c.util.getComponent("joinMember2").hide ? $c.util.getComponent("joinMember2").hide() : console.warn('[sdd] hide 대상 미해결: ' + "joinMember2"));
            ($c.util.getComponent("joinMember3") && $c.util.getComponent("joinMember3").hide ? $c.util.getComponent("joinMember3").hide() : console.warn('[sdd] hide 대상 미해결: ' + "joinMember3"));
        }
        fn_startBlink();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00006.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.cntr_cd = '' + dma_map.get("cntrIsoCd") + '';

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf00006.onpageload' });
    }
};


