/**
 * @method
 * @name scwin.registerMember
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.registerMember = async function () {
    /* sdd-asis-lifecycle:begin fn_registerMember — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF00006 || { elements: [] });
    scwin.chrg_tel_no.setValue($c.util.getComponent('ipt_chrgTelNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo3').getValue());
    scwin.encryp_cellphone_no.setValue($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue());
    scwin.chrg_fax_no.setValue($c.util.getComponent('ipt_chrgFaxNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo3').getValue());
    $c.util.getComponent("ipt_chrgInnrNo").setValue($c.util.getComponent('ipt_chrgInnrNo1').getValue());
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue().trim()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue().trim()) > 0) {
        $c.util.getComponent("dma_searchMemberReq").set("encrypChrgEmail", $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ "@" + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!$c.str.isEmail($c.util.getComponent("dma_searchMemberReq").get("encrypChrgEmail"))) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return;
    }
    fm.action = "/corp/register.do?method=registerMember";
    fm.target = "_self";
    await scwin.tx_fn_registerMember();
    /* sdd-asis-lifecycle:end */
};


